import os, sys, pty, select, time, fcntl, struct, termios, signal

def run(cmd, cols=100, rows=20, keys=b'', duration=1.5, env=None, quitkey=b'q', raw_exit=False):
    pid, fd = pty.fork()
    if pid == 0:
        e = dict(os.environ)
        e['TERM'] = 'xterm-256color'
        e['COLUMNS']=str(cols); e['LINES']=str(rows)
        if env: e.update(env)
        os.environ.clear(); os.environ.update(e)
        args = cmd.split() if isinstance(cmd,str) else cmd
        try:
            os.execvp(args[0], args)
        except Exception:
            os._exit(127)
    # parent
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    out = bytearray()
    deadline = time.time() + duration
    while time.time() < deadline:
        r,_,_ = select.select([fd],[],[],0.05)
        if r:
            try:
                d = os.read(fd, 65536)
            except OSError:
                break
            if not d: break
            out.extend(d)
        elif keys:
            k = keys[0]
            os.write(fd, k if isinstance(k,bytes) else k.encode())
            keys = keys[1:]
            deadline = time.time() + duration
    status = None
    try:
        os.waitpid(pid, os.WNOHANG)
    except Exception: pass
    try: os.kill(pid, signal.SIGKILL)
    except Exception: pass
    try: os.waitpid(pid,0)
    except Exception: pass
    try: os.close(fd)
    except Exception: pass
    return bytes(out)

if __name__ == '__main__':
    import argparse
    p = argparse.ArgumentParser()
    p.add_argument('--cmd', required=True)
    p.add_argument('--keys', default='')
    p.add_argument('--cols', type=int, default=100)
    p.add_argument('--rows', type=int, default=20)
    p.add_argument('--duration', type=float, default=1.5)
    p.add_argument('--hex', action='store_true')
    a = p.parse_args()
    keys = [k.encode() for k in a.keys.split(',')] if a.keys else []
    o = run(a.cmd, cols=a.cols, rows=a.rows, keys=keys, duration=a.duration)
    if a.hex:
        sys.stdout.write(repr(o))
    else:
        sys.stdout.buffer.write(o)
