func flagUsages(flags *pflag.FlagSet) string {
    var lines []string
    maxlen := 0
    flags.VisitAll(func(f *pflag.Flag) {
        if f.Hidden { return }
        var line string
        if f.Shorthand != "" {
            line = fmt.Sprintf("  -%s, --%s", f.Shorthand, f.Name)
        } else {
            line = fmt.Sprintf("      --%s", f.Name)
        }
        varname, usage := unquoteUsage(f)
        if varname != "" { line += " " + varname }
        if f.Value.Type() == "bool" && f.DefValue == "true" { line += "[=true|false]" }
        line += "\x00"
        if len(line) > maxlen { maxlen = len(line) }
        line += usage
        if !defaultIsZeroValue(f) {
            if f.Value.Type() == "string" { line += fmt.Sprintf(" (default %q)", f.DefValue) } else { line += fmt.Sprintf(" (default %s)", f.DefValue) }
        }
        lines = append(lines, line)
    })
    var buf bytes.Buffer
    for _, line := range lines {
        sidx := strings.Index(line, "\x00")
        spacing := strings.Repeat(" ", maxlen-sidx)
        buf.WriteString(line[:sidx] + " " + spacing + " " + line[sidx+1:] + "\n")
    }
    return buf.String()
}
```
