// General is a set of settings that are common to all view modes.
type General struct {
	Converter        string
	Caption          string
	ColumnDelimiter  string
	SectionDelimiter string
	JumpTarget       string
	TabWidth         int
	Header           int
	SkipLines        int
	MarkStyleWidth   int
	HScrollWidth     string
	VScrollLines     int
	AlternateRows    bool
	ColumnMode       bool
	LineNumMode      bool
	WrapMode         bool
	Prompt           PromptConfig
	Style            StyleConfigSet
}

// StyleConfig holds a single style.
type StyleConfig struct {
	Background     string
	Foreground     string
	UnderlineColor string
	UnderlineStyle string
	Blink          bool
	Bold           bool
	Dim            bool
	Italic         bool
	Reverse        bool
	Underline      bool
	StrikeThrough  bool
}

// StyleConfigSet holds all the styles that can be customized.
type StyleConfigSet struct {
	Header               StyleConfig
	Body                 StyleConfig
	LineNumber           StyleConfig
	SearchHighlight      StyleConfig
	ColumnHighlight      StyleConfig
	MarkLine             StyleConfig
	SectionLine          StyleConfig
	VerticalHeader       StyleConfig
	JumpTargetLine       StyleConfig
	Alternate            StyleConfig
	Ruler                StyleConfig
	HeaderBorder         StyleConfig
	SectionHeaderBorder  StyleConfig
	VerticalHeaderBorder StyleConfig
	MultiColorHighlight  []StyleConfig
	ColumnRainbow        []StyleConfig
}

// PromptConfig holds the prompt (status line) settings.
type PromptConfig struct {
	Normal PromptStyleConfig
	Input  PromptStyleConfig
}

// PromptStyleConfig holds the settings of a prompt.
type PromptStyleConfig struct {
	ShowFilename   bool
	InvertColor    bool
	ProcessOfCount bool
	CursorType     int
}

// Config is the whole configuration of ov.
type Config struct {
	Keybind             map[string][]string
	Mode                map[string]General
	ViewMode            string
	DefaultKeyBind      string
	Prompt              PromptConfig
	StyleOverStrike     StyleConfig
	StyleOverLine       StyleConfig
	General             General
	BeforeWriteOriginal int
	AfterWriteOriginal  int
	MemoryLimit         int
	MemoryLimitFile     int
	DisableMouse        bool
	IsWriteOriginal     bool
	QuitSmall           bool
	CaseSensitive       bool
	SmartCaseSensitive  bool
	RegexpSearch        bool
	Incsearch           bool
	NotifyEOF           int
	ReadWaitTime        time.Duration
	ClipboardMethod     string
	ShrinkChar          string
	DisableColumnCycle  bool
	DisableStickyFollow bool
	SetTerminalTitle    bool
	Debug               bool
}

// NewConfig returns the default configuration.
func NewConfig() *Config {
	c := &Config{}
	c.Keybind = DefaultKeyBind()
	c.Mode = map[string]General{}
	c.Incsearch = true
	c.MemoryLimit = -1
	c.MemoryLimitFile = 100
	c.ReadWaitTime = time.Second
	c.ShrinkChar = "\u2026"
	c.General = defaultGeneral()
	c.Prompt = PromptConfig{
		Normal: PromptStyleConfig{ShowFilename: true, InvertColor: true, ProcessOfCount: true},
		Input:  PromptStyleConfig{CursorType: 1},
	}
	return c
}

func defaultGeneral() General {
	return General{
		TabWidth:        8,
		ColumnDelimiter: ",",
		WrapMode:        true,
		MarkStyleWidth:  1,
		HScrollWidth:    "10%",
		VScrollLines:    2,
		Prompt: PromptConfig{
			Normal: PromptStyleConfig{ShowFilename: true, InvertColor: true, ProcessOfCount: true},
			Input:  PromptStyleConfig{CursorType: 1},
		},
	}
}

// SetDefaults fills in the values that have not been set.
func (c *Config) SetDefaults() {
	if c.Keybind == nil {
		c.Keybind = DefaultKeyBind()
	}
	if c.Mode == nil {
		c.Mode = map[string]General{}
	}
	if c.General.ColumnDelimiter == "" {
		c.General.ColumnDelimiter = ","
	}
	if c.General.HScrollWidth == "" {
		c.General.HScrollWidth = "10%"
	}
	if c.General.VScrollLines == 0 {
		c.General.VScrollLines = 2
	}
	if c.General.TabWidth == 0 {
		c.General.TabWidth = 8
	}
	if c.General.MarkStyleWidth == 0 {
		c.General.MarkStyleWidth = 1
	}
	if c.ReadWaitTime == 0 {
		c.ReadWaitTime = time.Second
	}
	if c.ShrinkChar == "" {
		c.ShrinkChar = "\u2026"
	}
}

// SupportedExts is the list of the extensions of the config files that can be read.
var SupportedExts = []string{"json", "toml", "yaml", "yml", "properties", "props", "prop", "hcl", "tfvars", "dotenv", "env", "ini"}

func configType(file string) string {
	ext := ""
	if i := strings.LastIndex(file, "."); i >= 0 {
		ext = file[i+1:]
	}
	ext = strings.ToLower(ext)
	for _, e := range SupportedExts {
		if e == ext {
			return ext
		}
	}
	return ""
}

// readConfigFile reads the config file and returns the settings.
func readConfigFile(file string) (map[string]interface{}, error) {
	switch configType(file) {
	case "yaml", "yml":
		var m map[string]interface{}
		b, err := os.ReadFile(file)
		if err != nil {
			return nil, err
		}
		if err := yaml.Unmarshal(b, &m); err != nil {
			return nil, fmt.Errorf("While parsing config: %s", err.Error())
		}
		if m == nil {
			m = map[string]interface{}{}
		}
		return m, nil
	case "json":
		var m map[string]interface{}
		b, err := os.ReadFile(file)
		if err != nil {
			return nil, err
		}
		if err := json.Unmarshal(b, &m); err != nil {
			return nil, fmt.Errorf("While parsing config: %s", err.Error())
		}
		if m == nil {
			m = map[string]interface{}{}
		}
		return m, nil
	case "toml":
		var m map[string]interface{}
		b, err := os.ReadFile(file)
		if err != nil {
			return nil, err
		}
		if err := toml.Unmarshal(b, &m); err != nil {
			return nil, fmt.Errorf("While parsing config: %s", err.Error())
		}
		if m == nil {
			m = map[string]interface{}{}
		}
		return m, nil
	case "env", "dotenv":
		b, err := os.ReadFile(file)
		if err != nil {
			return nil, err
		}
		return parseDotEnv(string(b))
	case "", "ini", "properties", "props", "prop", "hcl", "tfvars":
		if configType(file) == "" {
			return nil, fmt.Errorf("Unsupported Config Type %q", "")
		}
		return nil, fmt.Errorf("While parsing config: decoder not found for this format")
	}
	return nil, fmt.Errorf("Unsupported Config Type %q", configType(file))
}

// parseDotEnv parses a dotenv formatted file.
func parseDotEnv(s string) (map[string]interface{}, error) {
	m := map[string]interface{}{}
	for _, line := range strings.Split(s, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		i := strings.Index(line, "=")
		if i <= 0 {
			return nil, fmt.Errorf("While parsing config: line `%s` doesn't match format", line)
		}
		key := strings.TrimSpace(line[:i])
		val := strings.TrimSpace(line[i+1:])
		m[key] = strings.Trim(val, `"'`)
	}
	return m, nil
}

// decodeConfig decodes the settings into the config.
func decodeConfig(src map[string]interface{}, c *Config) error {
	errs := decodeStruct("", reflect.ValueOf(c).Elem(), src)
	if len(errs) == 0 {
		return nil
	}
	return &DecodeError{errs: errs}
}

// DecodeError is the error returned when the config could not be decoded.
type DecodeError struct {
	errs []error
}

func (e *DecodeError) Error() string {
	var sb strings.Builder
	sb.WriteString("decoding failed due to the following error(s):\n\n")
	for _, err := range e.errs {
		sb.WriteString(err.Error())
		sb.WriteString("\n")
	}
	return sb.String()
}

func typeOf(v interface{}) string {
	if v == nil {
		return "<nil>"
	}
	return fmt.Sprintf("%T", v)
}

// decodeStruct decodes a map into a struct.
func decodeStruct(prefix string, dst reflect.Value, src map[string]interface{}) []error {
	var errs []error
	t := dst.Type()
	for i := 0; i < t.NumField(); i++ {
		f := t.Field(i)
		fv := dst.Field(i)
		name := f.Name
		val, ok := lookup(src, name)
		if !ok {
			continue
		}
		path := name
		if prefix != "" {
			path = prefix + "." + name
		}
		errs = append(errs, decodeValue(path, fv, val)...)
	}
	return errs
}

func lookup(src map[string]interface{}, name string) (interface{}, bool) {
	lower := strings.ToLower(name)
	for k, v := range src {
		if strings.ToLower(k) == lower {
			return v, true
		}
	}
	return nil, false
}

func decodeValue(path string, fv reflect.Value, val interface{}) []error {
	if val == nil {
		return nil
	}
	switch fv.Kind() {
	case reflect.Struct:
		m, ok := val.(map[string]interface{})
		if !ok {
			return []error{fmt.Errorf("'%s' expected a map or struct, got %q", path, typeName(val))}
		}
		if fv.Type() == reflect.TypeOf(time.Duration(0)) {
			return nil
		}
		return decodeStruct(path, fv, m)
	case reflect.Map:
		m, ok := val.(map[string]interface{})
		if !ok {
			return []error{fmt.Errorf("'%s' expected type '%s', got unconvertible type '%s'", path, fv.Type().String(), typeName(val))}
		}
		var errs []error
		for k, v := range m {
			key := reflect.New(fv.Type().Key()).Elem()
			errs = append(errs, setBasic(path+"["+k+"]", key, k)...)
			elem := reflect.New(fv.Type().Elem()).Elem()
			errs = append(errs, decodeValue(path+"["+k+"]", elem, v)...)
			fv.SetMapIndex(key, elem)
		}
		return errs
	case reflect.Slice:
		arr, ok := val.([]interface{})
		if !ok {
			if s, ok := val.(string); ok && fv.Type().Elem().Kind() == reflect.String {
				fv.Set(reflect.ValueOf(strings.Split(s, ",")))
				return nil
			}
			return []error{fmt.Errorf("'%s' source data must be an array or slice, got %s", path, typeName(val))}
		}
		out := reflect.MakeSlice(fv.Type(), len(arr), len(arr))
		var errs []error
		for i, v := range arr {
			elem := out.Index(i)
			errs = append(errs, decodeValue(fmt.Sprintf("%s[%d]", path, i), elem, v)...)
		}
		fv.Set(out)
		return errs
	case reflect.Ptr:
		if fv.IsNil() {
			fv.Set(reflect.New(fv.Type().Elem()))
		}
		return decodeValue(path, fv.Elem(), val)
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		if fv.Type() == reflect.TypeOf(time.Duration(0)) {
			switch v := val.(type) {
			case string:
				d, err := time.ParseDuration(v)
				if err != nil {
					return []error{fmt.Errorf("'%s' %s", path, durationErr(err))}
				}
				fv.SetInt(int64(d))
				return nil
			}
		}
		var errs []error
		var n int64
		switch v := val.(type) {
		case int:
			n = int64(v)
		case int64:
			n = v
		case float64:
			n = int64(v)
		case bool:
			if v {
				n = 1
			}
		case string:
			i, err := strconv.ParseInt(v, 10, 64)
			if err != nil {
				return []error{fmt.Errorf("'%s' cannot parse value as 'int': %s", path, intErr(err))}
			}
			n = i
		case []interface{}:
			return []error{fmt.Errorf("'%s' expected type '%s', got unconvertible type '%s'", path, fv.Type().String(), typeName(val))}
		default:
			return []error{fmt.Errorf("'%s' expected type '%s', got unconvertible type '%s'", path, fv.Type().String(), typeName(val))}
		}
		if !fv.OverflowInt(n) {
			fv.SetInt(n)
		}
		return errs
	case reflect.Uint, reflect.Uint8, reflect.Uint16, reflect.Uint32, reflect.Uint64:
		var n uint64
		switch v := val.(type) {
		case int:
			n = uint64(v)
		case int64:
			n = uint64(v)
		case float64:
			n = uint64(v)
		case bool:
			if v {
				n = 1
			}
		case string:
			i, err := strconv.ParseUint(v, 10, 64)
			if err != nil {
				return []error{fmt.Errorf("'%s' cannot parse value as 'uint': %s", path, intErr(err))}
			}
			n = i
		default:
			return []error{fmt.Errorf("'%s' expected type '%s', got unconvertible type '%s'", path, fv.Type().String(), typeName(val))}
		}
		if !fv.OverflowUint(n) {
			fv.SetUint(n)
		}
		return nil
	case reflect.Bool:
		switch v := val.(type) {
		case bool:
			fv.SetBool(v)
		case int:
			fv.SetBool(v != 0)
		case int64:
			fv.SetBool(v != 0)
		case float64:
			fv.SetBool(v != 0)
		case string:
			b, err := strconv.ParseBool(v)
			if err != nil {
				return []error{fmt.Errorf("'%s' cannot parse value as 'bool': %s", path, boolErr(err))}
			}
			fv.SetBool(b)
		default:
			return []error{fmt.Errorf("'%s' expected type '%s', got unconvertible type '%s'", path, fv.Type().String(), typeName(val))}
		}
		return nil
	case reflect.String:
		switch v := val.(type) {
		case string:
			fv.SetString(v)
		case int:
			fv.SetString(strconv.Itoa(v))
		case int64:
			fv.SetString(strconv.FormatInt(v, 10))
		case float64:
			fv.SetString(strconv.FormatFloat(v, 'f', -1, 64))
		case bool:
			fv.SetString(strconv.FormatBool(v))
		default:
			return []error{fmt.Errorf("'%s' expected type 'string', got unconvertible type '%s'", path, typeName(val))}
		}
		return nil
	}
	return nil
}

func typeName(v interface{}) string {
	return strings.TrimPrefix(fmt.Sprintf("%T", v), "")
}

func intErr(err error) string {
	s := err.Error()
	if i := strings.Index(s, "parsing"); i >= 0 {
		return s[i:]
	}
	return s
}

func boolErr(err error) string {
	s := err.Error()
	if i := strings.Index(s, "parsing"); i >= 0 {
		return s[i:]
	}
	return s
}

func durationErr(err error) string {
	s := err.Error()
	if i := strings.Index(s, ":"); i >= 0 {
		s = s[i+1:]
	}
	if i := strings.Index(s, "\""); i >= 0 {
		s = s[:i]
	}
	return "time" + strings.TrimSuffix(s, " ")
}
