// SupportedExts is the list of the extensions of the config files that can be read.
var SupportedExts = []string{"json", "toml", "yaml", "yml", "properties", "props", "prop", "hcl", "tfvars", "dotenv", "env", "ini"}

func configType(file string) string {
	ext := ""
	if i := strings.LastIndex(file, "."); i >= 0 {
		ext = file[i+1:]
	}
	ext = strings.ToLower(ext)
	for _, e := range SupportedExts {
		if e == ext {
			return ext
		}
	}
	return ""
}

// readConfigFile reads the config file and returns the settings.
func readConfigFile(file string) (map[string]interface{}, error) {
	switch configType(file) {
	case "yaml", "yml":
		var m map[string]interface{}
		b, err := os.ReadFile(file)
		if err != nil {
			return nil, err
		}
		if err := yaml.Unmarshal(b, &m); err != nil {
			return nil, fmt.Errorf("While parsing config: %s", err.Error())
		}
		if m == nil {
			m = map[string]interface{}{}
		}
		return m, nil
	case "json":
		var m map[string]interface{}
		b, err := os.ReadFile(file)
		if err != nil {
			return nil, err
		}
		if err := json.Unmarshal(b, &m); err != nil {
			return nil, fmt.Errorf("While parsing config: %s", err.Error())
		}
		if m == nil {
			m = map[string]interface{}{}
		}
		return m, nil
	case "toml":
		var m map[string]interface{}
		b, err := os.ReadFile(file)
		if err != nil {
			return nil, err
		}
		if err := toml.Unmarshal(b, &m); err != nil {
			return nil, fmt.Errorf("While parsing config: %s", err.Error())
		}
		if m == nil {
			m = map[string]interface{}{}
		}
		return m, nil
	case "env", "dotenv":
		b, err := os.ReadFile(file)
		if err != nil {
			return nil, err
		}
		return parseDotEnv(string(b))
	case "", "ini", "properties", "props", "prop", "hcl", "tfvars":
		if configType(file) == "" {
			return nil, fmt.Errorf("Unsupported Config Type %q", "")
		}
		return nil, fmt.Errorf("While parsing config: decoder not found for this format")
	}
	return nil, fmt.Errorf("Unsupported Config Type %q", configType(file))
}

// parseDotEnv parses a dotenv formatted file.
func parseDotEnv(s string) (map[string]interface{}, error) {
	m := map[string]interface{}{}
	for _, line := range strings.Split(s, "\n") {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		i := strings.Index(line, "=")
		if i <= 0 {
			return nil, fmt.Errorf("While parsing config: line `%s` doesn't match format", line)
		}
		key := strings.TrimSpace(line[:i])
		val := strings.TrimSpace(line[i+1:])
		m[key] = strings.Trim(val, `"'`)
	}
	return m, nil
}

// decodeConfig decodes the settings into the config.
func decodeConfig(src map[string]interface{}, c *Config) error {
	errs := decodeStruct("", reflect.ValueOf(c).Elem(), src)
	if len(errs) == 0 {
		return nil
	}
	return &DecodeError{errs: errs}
}

// DecodeError is the error returned when the config could not be decoded.
type DecodeError struct {
	errs []error
}

func (e *DecodeError) Error() string {
	var sb strings.Builder
	sb.WriteString("decoding failed due to the following error(s):\n\n")
	for _, err := range e.errs {
		sb.WriteString(err.Error())
		sb.WriteString("\n")
	}
	return sb.String()
}

func typeOf(v interface{}) string {
	if v == nil {
		return "<nil>"
	}
	return fmt.Sprintf("%T", v)
}

// decodeStruct decodes a map into a struct.
func decodeStruct(prefix string, dst reflect.Value, src map[string]interface{}) []error {
	var errs []error
	t := dst.Type()
	for i := 0; i < t.NumField(); i++ {
		f := t.Field(i)
		fv := dst.Field(i)
		name := f.Name
		val, ok := lookup(src, name)
		if !ok {
