		}
		path := name
		if prefix != "" {
			path = prefix + "." + name
		}
		errs = append(errs, decodeValue(path, fv, val)...)
	}
	return errs
}

func lookup(src map[string]interface{}, name string) (interface{}, bool) {
	lower := strings.ToLower(name)
	for k, v := range src {
