func intErr(err error) string {
	s := err.Error()
	if i := strings.Index(s, "parsing"); i >= 0 {
		return s[i:]
	}
	return s
}

func boolErr(err error) string {
	s := err.Error()
	if i := strings.Index(s, "parsing"); i >= 0 {
		return s[i:]
	}
	return s
}

func durationErr(err error) string {
	s := err.Error()
	if i := strings.Index(s, ":"); i >= 0 {
		s = s[i+1:]
	}
	if i := strings.Index(s, "\""); i >= 0 {
		s = s[:i]
	}
