{"command": "cat > /workspace/oviewer/completion.go <<'GOEOF'
package oviewer

import (
	"github.com/spf13/cobra"
	"github.com/spf13/pflag"
)

// registerCompletion registers the completion functions of the flags.
func registerCompletion(flags *pflag.FlagSet) {
}

// registerFlagCompletion registers the completion functions of the flags of the command.
func registerFlagCompletion(cmd *cobra.Command) {
	_ = cmd.RegisterFlagCompletionFunc("column-delimiter", func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
		return []cobra.Completion{
			cobra.CompletionWithDesc(",", "comma"),
			cobra.CompletionWithDesc("|", "vertical line"),
			cobra.CompletionWithDesc("\\t", "tab"),
			cobra.CompletionWithDesc("│", "box"),
		}, cobra.ShellCompDirectiveNoFileComp
	})
	_ = cmd.RegisterFlagCompletionFunc("completion", cobra.FixedCompletions([]cobra.Completion{
		"bash", "zsh", "fish", "powershell",
	}, cobra.ShellCompDirectiveNoFileComp))
	_ = cmd.RegisterFlagCompletionFunc("config", func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
		return []cobra.Completion{"yaml"}, cobra.ShellCompDirectiveFilterFileExt
	})
	_ = cmd.RegisterFlagCompletionFunc("converter", func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
		return []cobra.Completion{
			cobra.CompletionWithDesc("es", "Escape Sequence"),
			cobra.CompletionWithDesc("raw", "Raw output of escape sequences"),
			cobra.CompletionWithDesc("align", "Align Column Widths"),
		}, cobra.ShellCompDirectiveNoFileComp
	})
	for _, name := range []string{"header", "header-column", "skip-lines", "vertical-header"} {
		_ = cmd.RegisterFlagCompletionFunc(name, func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
			return []cobra.Completion{"1"}, cobra.ShellCompDirectiveNoFileComp
		})
	}
	_ = cmd.RegisterFlagCompletionFunc("tab-width", func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
		return []cobra.Completion{
			cobra.CompletionWithDesc("3", "tab width"),
			cobra.CompletionWithDesc("2", "tab width"),
