// run is the entry point of the command.
func (o *Oviewer) run(version, revision string) error {
	if o.Version {
		fmt.Printf("ov version %s rev:%s\n", version, revision)
		return nil
	}
	registerFlagCompletion(o.cmd)
	snap := o.snapshotFlags()
	o.loadConfig()
	o.applySnapshot(snap, o.cmd.Flags())

	if o.HelpKey {
		fmt.Print(HelpKeyBind(o.config.Keybind))
		return nil
	}
	if o.ListViewModes {
		for _, m := range o.listViewModes() {
			fmt.Println(m)
		}
		return nil
	}
	if o.Completion != "" {
		switch o.Completion {
		case "bash":
			return o.cmd.GenBashCompletion(os.Stdout)
		case "zsh":
			return o.cmd.GenZshCompletion(os.Stdout)
		case "fish":
			return o.cmd.GenFishCompletion(os.Stdout, true)
		case "powershell":
			return o.cmd.GenPowerShellCompletion(os.Stdout)
		}
		return fmt.Errorf("requires one of the arguments bash/zsh/fish/powershell")
	}

	return o.mainLoop()
}

// listViewModes returns the list of the view modes.
func (o *Oviewer) listViewModes() []string {
	modes := []string{}
	for name := range o.config.Mode {
		modes = append(modes, name)
	}
	sort.Strings(modes)
	modes = append(modes, "general")
	return modes
}

// xdgConfigHome returns the XDG config home directory.
func xdgConfigHome() string {
	if dir, err := os.UserConfigDir(); err == nil && dir != "" {
		return dir
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return ""
	}
	return filepath.Join(home, ".config")
}

// loadConfig reads the config file.
func (o *Oviewer) loadConfig() {
	var (
		src  map[string]interface{}
		err  error
		used string
	)
	if o.ConfigFile != "" {
		used = o.ConfigFile
		src, err = readConfigFile(o.ConfigFile)
	} else {
		dir := filepath.Join(xdgConfigHome(), appName)
		for _, ext := range SupportedExts {
			f := filepath.Join(dir, "config."+ext)
			if _, e := os.Stat(f); e == nil {
				used = f
				src, err = readConfigFile(f)
				break
			}
		}
		if used == "" {
			err = fmt.Errorf("Config File %q Not Found in %q", "config", fmt.Sprintf("%s", []string{dir}))
		}
	}
	if err != nil {
		if o.Debug || o.ConfigFile != "" {
			fmt.Fprintf(os.Stderr, "failed to read config file: %s\n", err)
		}
		if o.Debug && o.ConfigFile == "" {
			fmt.Fprintln(os.Stderr, "config file not found")
		}
	}
	if used != "" {
		if err == nil {
			if e := decodeConfig(src, o.config); e != nil {
				fmt.Fprintln(os.Stderr, e.Error())
			}
		}
		if o.Debug {
			fmt.Fprintf(os.Stderr, "Using config file: %s\n", used)
		}
	}
	o.config.SetDefaults()
	o.applyConfig()
}

// applyConfig applies the config and the view mode to the settings.
func (o *Oviewer) applyConfig() {
	g := o.config.General
	if o.ViewMode != "" {
		for name, mode := range o.config.Mode {
			if strings.EqualFold(name, o.ViewMode) {
				g = mergeGeneral(g, mode)
				break
			}
		}
	}
	o.General = g
	o.Keybind = o.config.Keybind
	o.QuitSmall = o.config.QuitSmall
	o.IsWriteOriginal = o.config.IsWriteOriginal
	o.ExitWriteBefore = o.config.BeforeWriteOriginal
	o.ExitWriteAfter = o.config.AfterWriteOriginal
	o.CaseSensitive = o.config.CaseSensitive
	o.SmartCaseSensitive = o.config.SmartCaseSensitive
	o.RegexpSearch = o.config.RegexpSearch
	o.Incsearch = o.config.Incsearch
	o.MemoryLimit = o.config.MemoryLimit
	o.MemoryLimitFile = o.config.MemoryLimitFile
	o.DisableMouse = o.config.DisableMouse
	o.DisableColumnCycle = o.config.DisableColumnCycle
	o.DisableStickyFollow = o.config.DisableStickyFollow
	o.ViewMode = o.config.ViewMode
	o.SetTerminalTitle = o.config.SetTerminalTitle
	o.NotifyEOF = o.config.NotifyEOF
	o.TabWidth = g.TabWidth
	o.Header = g.Header
	o.AlternateRows = g.AlternateRows
	o.ColumnMode = g.ColumnMode
	o.LineNumber = g.LineNumMode
	o.Wrap = g.WrapMode
	o.ColumnDelimiter = g.ColumnDelimiter
	o.SectionDelimiter = g.SectionDelimiter
	o.SkipLines = g.SkipLines
	o.Caption = g.Caption
	o.Converter = g.Converter
	o.JumpTarget = g.JumpTarget
	o.HScrollWidth = g.HScrollWidth
	o.VerticalHeader = 0
	o.HeaderColumn = 0
	o.StatusLine = true
}

// mergeGeneral merges the mode settings into the general settings.
func mergeGeneral(dst, src General) General {
	if src.Converter != "" {
		dst.Converter = src.Converter
	}
	if src.Caption != "" {
		dst.Caption = src.Caption
	}
	if src.ColumnDelimiter != "" {
