		dst.JumpTarget = src.JumpTarget
	}
	if src.TabWidth != 0 {
		dst.TabWidth = src.TabWidth
	}
	if src.Header != 0 {
		dst.Header = src.Header
	}
	if src.SkipLines != 0 {
		dst.SkipLines = src.SkipLines
	}
	if src.MarkStyleWidth != 0 {
		dst.MarkStyleWidth = src.MarkStyleWidth
	}
	if src.HScrollWidth != "" {
		dst.HScrollWidth = src.HScrollWidth
	}
	if src.VScrollLines != 0 {
		dst.VScrollLines = src.VScrollLines
	}
