{"command": "cat > /workspace/oviewer/doc.go <<'GOEOF'
package oviewer

import (
	"bytes"
	"compress/bzip2"
	"compress/gzip"
	"io"
	"os"
	"strings"
	"sync"
)

// Document holds the content of a document.
type Document struct {
	// Name is the name of the document (the file name or "(STDIN)").
	Name string
	// FileName is the file name of the document.
	FileName string

	mu     sync.RWMutex
	lines  []string
	reading bool
	eof    bool

	// the header lines
	Header int
	// the skip lines
	SkipLines int

	// marks
	marks map[int]bool

	// section
	sectionDelimiter string
	sections         []int

	// wrap height cache
	wrapCache map[wrapKey]map[int]int
}

type wrapKey struct {
	width int
	tab   int
}

// NewDocument returns a new Document.
func NewDocument() *Document {
	d := &Document{
		marks:     map[int]bool{},
		wrapCache: map[wrapKey]map[int]int{},
	}
	return d
}

// Len returns the number of lines.
func (d *Document) Len() int {
	d.mu.RLock()
	defer d.mu.RUnlock()
	return len(d.lines)
}

// Reading returns true if the document is still reading.
func (d *Document) Reading() bool {
	return d.reading
}

// GetLine returns the line of the specified number.
func (d *Document) GetLine(n int) string {
	d.mu.RLock()
	defer d.mu.RUnlock()
	if n < 0 || n >= len(d.lines) {
		return ""
	}
	return d.lines[n]
}

// getLines returns the lines from start to end.
func (d *Document) getLines(start, end int) []string {
	d.mu.RLock()
	defer d.mu.RUnlock()
	if start < 0 {
		start = 0
	}
	if end > len(d.lines) {
		end = len(d.lines)
	}
	if start >= end {
		return nil
	}
	return d.lines[start:end]
}

// appendLines appends the lines.
func (d *Document) appendLines(lines []string) {
	d.mu.Lock()
	defer d.mu.Unlock()
	d.lines = append(d.lines, lines...)
}

// setLines sets the lines.
func (d *Document) setLines(lines []string) {
	d.mu.Lock()
	defer d.mu.Unlock()
	d.lines = lines
}

// addMark adds a mark at the line.
func (d *Document) addMark(n int) {
	d.mu.Lock()
	defer d.mu.Unlock()
	d.marks[n] = true
}

// removeMark removes a mark at the line.
func (d *Document) removeMark(n int) {
	d.mu.Lock()
