	defer f.Close()
	return readDocumentReader(d, fileName, f, true)
}

// readDocumentStream reads from the reader.
func readDocumentStream(d *Document, r io.Reader) error {
	return readDocumentReader(d, "", r, false)
}

// readDocumentReader reads the lines from the reader.
func readDocumentReader(d *Document, fileName string, r io.Reader, tryDecompress bool) error {
	buf := make([]byte, 64*1024)
	head, err := io.ReadFull(r, buf)
	if err != nil && err != io.ErrUnexpectedEOF {
		if err == io.EOF {
			return nil
		}
		return err
	}
	head = head
	if tryDecompress {
		if comp := isCompressed(buf); comp != "" {
			br := io.MultiReader(bytes.NewReader(buf), r)
			dr, closeFn, err := decompressReader(comp, br)
			if err != nil {
				return err
			}
			if closeFn != nil {
				defer closeFn()
			}
			return readLines(d, dr)
		}
	}
	br := io.MultiReader(bytes.NewReader(buf), r)
	return readLines(d, br)
}

// readLines reads the lines.
func readLines(d *Document, r io.Reader) error {
	const chunkSize = 4096
	lines := make([]string, 0, chunkSize)
	buffer := make([]byte, 0, 64*1024)
	tmp := make([]byte, 64*1024)
	for {
		n, err := r.Read(tmp)
		if n > 0 {
			buffer = append(buffer, tmp[:n]...)
			idx := bytes.IndexByte(buffer, '\n')
			for idx >= 0 {
				line := buffer[:idx]
				line = bytes.TrimSuffix(line, []byte("\r"))
				lines = append(lines, string(line))
				buffer = buffer[idx+1:]
				if len(lines) >= chunkSize {
					d.appendLines(lines)
					lines = make([]string, 0, chunkSize)
				}
				idx = bytes.IndexByte(buffer, '\n')
			}
		}
		if err != nil {
			break
		}
	}
	if len(buffer) > 0 {
		line := bytes.TrimSuffix(buffer, []byte("\r"))
		lines = append(lines, string(line))
	}
	if len(lines) > 0 {
		d.appendLines(lines)
	}
	return nil
}

// sortInts sorts the ints.
func sortInts(a []int) {
	for i := 1; i < len(a); i++ {
		for j := i; j > 0 && a[j] < a[j-1]; j-- {
			a[j], a[j-1] = a[j-1], a[j]
		}
	}
}

// setSectionDelimiter sets the section delimiter.
func (d *Document) setSectionDelimiter(re string) {
	d.mu.Lock()
	d.sectionDelimiter = re
	d.mu.Unlock()
}

// findSections finds the section start lines.
func (d *Document) findSections(re *Regexp) {
}

// isSectionLine returns true if the line is a section delimiter.
func (d *Document) isSectionLine(line string) bool {
	if d.sectionDelimiter == "" {
		return false
	}
	return sectionMatch(d.sectionDelimiter, line)
}

var sectionCache = map[string]*Regexp{}

func sectionMatch(re string, line string) bool {
	r, ok := sectionCache[re]
	if !ok {
		r = newRegexp(re)
		sectionCache[re] = r
	}
	return r.MatchString(line)
}

// truncateLine truncates the line.
func truncateLine(s string, n int) string {
	if len(s) <= n {
		return s
	}
	return s[:n]
}

// isEmpty returns true if the string is empty.
func isEmpty(s string) bool {
	return strings.TrimSpace(s) == ""
}
