package oviewer

import (
	tcell "github.com/gdamore/tcell/v2"
	"unicode/utf8"
)

// Cell is a display cell.
type Cell struct {
	r rune
	w int
	s tcell.Style
}

// wrapLineHeight returns the number of the display rows of the line.
func wrapLineHeight(s string, width, tabWidth int) int {
	if width <= 0 {
		return 1
	}
	if s == "" {
		return 1
	}
	w := 0
	n := 1
	for _, c := range convertCells(s, tabWidth) {
		if c.w == 0 {
			continue
		}
		if w+c.w > width {
			n++
			w = c.w
		} else {
			w += c.w
		}
	}
	return n
}

// convertCells converts a line into display cells.
func convertCells(s string, tabWidth int) []Cell {
	cells := make([]Cell, 0, len(s))
	var st tcell.Style
	i := 0
	for i < len(s) {
		c, size := utf8.DecodeRuneInString(s[i:])
		if c == '\t' {
			if tabWidth <= 0 {
				cells = append(cells, Cell{r: ' ', w: 1})
				i += size
				continue
			}
			// expand the tab to the next tab stop
			pos := 0
			for _, cell := range cells {
				pos += cell.w
			}
			next := ((pos / tabWidth) + 1) * tabWidth
			if next <= pos {
				next = pos + tabWidth
			}
			for j := 0; j < next-pos; j++ {
				cells = append(cells, Cell{r: ' ', w: 1, s: st})
			}
			i += size
			continue
		}
		if c == 0x1b {
			// escape sequence
			if seq, n := parseEscapeSequence(s[i:]); n > 0 {
				st = applyStyleSeq(st, seq)
				i += n
				continue
			}
		}
		w := runewidthRune(c)
		cells = append(cells, Cell{r: c, w: w, s: st})
		i += size
	}
	return cells
}

// runewidthRune returns the display width of the rune.
func runewidthRune(c rune) int {
	if c == 0 {
		return 0
	}
	if c < 32 || (c >= 0x7f && c < 0xa0) {
		return 0
	}
	return runeWidth(c)
}
GOEOF
