package oviewer

import (
	"unicode"
)

// ranges of the East Asian Wide and Fullwidth characters.
type rrange struct {
	first, last rune
}

var doubleWidth = []rrange{
	{0x1100, 0x115F},
	{0x2329, 0x232A},
	{0x2E80, 0x303E},
	{0x3041, 0x33FF},
	{0x3400, 0x4DBF},
	{0x4E00, 0x9FFF},
	{0xA000, 0xA4CF},
	{0xA4D0, 0xA95F},
	{0xA960, 0xA97F},
	{0xAC00, 0xD7A3},
	{0xF900, 0xFAFF},
	{0xFE10, 0xFE19},
	{0xFE30, 0xFE6F},
	{0xFF00, 0xFF60},
	{0xFFE0, 0xFFE6},
	{0x1F300, 0x1F64F},
	{0x1F900, 0x1F9FF},
	{0x20000, 0x2FFFD},
	{0x30000, 0x3FFFD},
}

// runeWidth returns the width of the rune.
func runeWidth(c rune) int {
	if c == 0 {
		return 0
	}
	if c < 0x20 || (c >= 0x7f && c < 0xa0) {
		return 0
	}
	if c == 0x0300 {
		return 0
	}
	if isCombining(c) {
		return 0
	}
	if isWide(c) {
		return 2
	}
	return 1
}

func isWide(c rune) bool {
	lo, hi := 0, len(doubleWidth)-1
	for lo <= hi {
		mid := (lo + hi) / 2
		switch {
		case doubleWidth[mid].last < c:
			lo = mid + 1
		case doubleWidth[mid].first > c:
			hi = mid - 1
		default:
			return true
		}
	}
	return false
}

// combining characters
var combiningRanges = []rrange{
	{0x0300, 0x036F},
	{0x0483, 0x0489},
	{0x0591, 0x05BD},
	{0x0610, 0x061A},
	{0x064B, 0x065F},
	{0x0670, 0x0670},
	{0x06D6, 0x06DC},
	{0x0900, 0x0903},
	{0x093A, 0x093A},
	{0x1AB0, 0x1AFF},
	{0x1DC0, 0x1DFF},
	{0x20D0, 0x20F0},
	{0xFE00, 0xFE0F},
	{0xFE20, 0xFE2F},
}

func isCombining(c rune) bool {
	for _, r := range combiningRanges {
		if c >= r.first && c <= r.last {
			return true
		}
	}
	return false
}

// isPrint returns true if the rune is printable.
func isPrint(c rune) bool {
	return unicode.IsPrint(c)
}
