package oviewer

import (
	"strings"

	tcell "github.com/gdamore/tcell/v2"
)

// parseEscapeSequence parses the escape sequence at the head of the string.
// It returns the sequence and the length of it.
func parseEscapeSequence(s string) (string, int) {
	if len(s) < 2 || s[1] != '[' {
		return "", 0
	}
	i := 2
	for i < len(s) {
		c := s[i]
		if (c >= '0' && c <= '9') || c == ';' || c == '?' || c == ':' || c == '<' || c == '=' || c == '>' || c == ' ' || c == '!' || c == '"' || c == '$' || c == '\'' {
			i++
			continue
		}
		i++
		return s[:i], i
	}
	return "", 0
}

// applyStyleSeq applies the escape sequence to the style.
func applyStyleSeq(st tcell.Style, seq string) tcell.Style {
	if len(seq) < 3 {
		return st
	}
	body := seq[2 : len(seq)-1]
	mode := seq[len(seq)-1]
	if mode != 'm' {
		return st
	}
	params := strings.Split(body, ";")
	if len(params) == 0 {
		params = []string{""}
	}
	i := 0
	if body == "" {
		return tcell.StyleDefault
	}
	for i < len(params) {
		p := params[i]
		i++
		n := atoi(p)
		switch {
		case n == 0:
			st = tcell.StyleDefault
		case n == 1:
			st = st.Bold(true)
		case n == 2:
			st = st.Dim(true)
		case n == 3:
			st = st.Italic(true)
		case n == 4:
			st = st.Underline(true)
		case n == 5:
			st = st.Blink(true)
		case n == 7:
			st = st.Reverse(true)
		case n == 8:
			st = st.Dim(true)
		case n == 9:
			st = st.StrikeThrough(true)
		case n == 21:
			st = st.Bold(false)
		case n == 22:
			st = st.Bold(false).Dim(false)
		case n == 23:
			st = st.Italic(false)
		case n == 24:
			st = st.Underline(false)
		case n == 25:
			st = st.Blink(false)
		case n == 27:
			st = st.Reverse(false)
		case n == 28:
			st = st.Dim(false)
		case n == 29:
			st = st.StrikeThrough(false)
		case n >= 30 && n <= 37:
			st = st.Foreground(tcell.Color(n - 30))
		case n == 38 || n == 48:
			color, adv := parseExtColor(params[i:])
			if adv > 0 {
				i += adv
			}
			c := color
			if n == 38 {
				st = st.Foreground(c)
			} else {
				st = st.Background(c)
			}
		case n == 39:
			st = st.Foreground(tcell.ColorDefault)
		case n == 49:
			st = st.Background(tcell.ColorDefault)
		case n >= 90 && n <= 97:
			st = st.Foreground(tcell.Color(n - 90 + 8))
		case n >= 100 && n <= 107:
			st = st.Background(tcell.Color(n - 100 + 8))
		}
	}
	return st
}

// parseExtColor parses the extended color.
func parseExtColor(params []string) (tcell.Color, int) {
	if len(params) == 0 {
		return tcell.ColorDefault, 0
	}
	switch params[0] {
	case "5":
		if len(params) > 1 {
			n := atoi(params[1])
			return tcell.Color(n), 2
		}
		return tcell.ColorDefault, 1
	case "2":
		if len(params) > 3 {
			r := atoi(params[1])
			g := atoi(params[2])
			b := atoi(params[3])
			return tcell.NewRGBColor(int32(r), int32(g), int32(b)), 4
		}
		return tcell.ColorDefault, 1
	}
	return tcell.ColorDefault, 0
}

// atoi converts the string to an int.
func atoi(s string) int {
	n := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c < '0' || c > '9' {
			return 0
		}
		n = n*10 + int(c-'0')
	}
	return n
}
GOEOF
