import os, sys, pty, select, time, fcntl, struct, termios, signal, re

RESP = {
    b'\x1b[18t': b'\x1b[8;{rows};{cols}t',
    b'\x1b[?2048$p': b'\x1b[?2048;2$y',
    b'\x1b[?1000$p': b'\x1b[?1000;2$y',
    b'\x1b[?1006$p': b'\x1b[?1006;2$y',
    b'\x1b[>q': b'\x1b[>1;2q',
    b'\x1b[c': b'\x1b[?62;22;6c',
    b'\x1b[>0q': b'\x1b[>0;1q',
    b'\x1b[>4;2q': b'\x1b[>4;2q',
}

def run(cmd, cols=100, rows=20, keys=b'', duration=3.0, env=None, reply=True):
    pid, fd = pty.fork()
    if pid == 0:
        e = dict(os.environ); e['TERM']='xterm-256color'; e['COLUMNS']=str(cols); e['LINES']=str(rows)
        if env: e.update(env)
        os.environ.clear(); os.environ.update(e)
        args = cmd.split() if isinstance(cmd,str) else cmd
        try: os.execvp(args[0], args)
        except Exception: os._exit(127)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    t0=time.time(); deadline=t0+duration; buf=bytearray(); events=[]
    while time.time() < deadline:
        r,_,_=select.select([fd],[],[],0.05)
        if r:
            try: d=os.read(fd,65536)
            except OSError: break
            if not d: break
            events.append((round((time.time()-t0)*1000), d))
            buf.extend(d)
            if reply:
                # respond to queries
                for q,t in RESP.items():
                    if q in d:
                        s=t.replace(b'{rows}', str(rows).encode()).replace(b'{cols}', str(cols).encode())
                        try: os.write(fd, s)
                        except OSError: pass
        elif keys:
            k = keys[0]
            os.write(fd, k if isinstance(k,bytes) else k.encode())
            keys = keys[1:]
            deadline = time.time() + duration
    try: os.kill(pid, signal.SIGKILL)
    except Exception: pass
    try: os.waitpid(pid,0)
    except Exception: pass
    try: os.close(fd)
    except Exception: pass
    return bytes(buf), events

if __name__=='__main__':
    import argparse
    p=argparse.ArgumentParser(); p.add_argument('--cmd',required=True); p.add_argument('--keys',default=''); p.add_argument('--cols',type=int,default=100); p.add_argument('--rows',type=int,default=20); p.add_argument('--duration',type=float,default=3.0); p.add_argument('--show',action='store_true'); p.add_argument('--hex',action='store_true'); p.add_argument('--noreply',action='store_true')
