// terminfoOV returns the terminfo that ov uses.
func terminfoOV() *terminfo.Terminfo {
	ti := &terminfo.Terminfo{}
	ti.Name = "xterm-256color"
	ti.Columns = 80
	ti.Lines = 24
	ti.Colors = 256
	ti.Clear = "\x1b[H\x1b[J"
	ti.EnterCA = "\x1b[?1049h"
	ti.ExitCA = "\x1b[?1049l"
	ti.ShowCursor = "\x1b[?25h"
	ti.HideCursor = "\x1b[?25l"
	ti.AttrOff = "\x1b[m"
	ti.Underline = "\x1b[4m"
	ti.Bold = "\x1b[1m"
	ti.Blink = "\x1b[5m"
	ti.Reverse = "\x1b[7m"
	ti.Dim = "\x1b[2m"
	ti.Italic = "\x1b[3m"
	ti.StrikeThrough = "\x1b[9m"
	ti.EnterKeypad = "\x1b[?1h\x1b="
	ti.ExitKeypad = "\x1b[?1l\x1b>"
	ti.SetFg = "\x1b[%?%p1%{8}%<%t3%p1%d%e38;5;%p1%d%;m"
	ti.SetBg = "\x1b[%?%p1%{8}%<%t4%p1%d%e48;5;%p1%d%;m"
	ti.Mouse = "\x1b[<"
	ti.SetCursor = "\x1b[%i%p1%d;%p2%dH"
