	ti.DisableAutoMargin = "\x1b[?7l"
	ti.EnableAutoMargin = "\x1b[?7h"
	ti.EnableAcs = "\x1b(B\x1b)0"
	ti.XTermLike = true
	return ti
}

// queryTerminal writes the capability queries and waits for the responses.
func queryTerminal(tty *os.File, timeout time.Duration) {
	os.Stdout.WriteString("\x1b[18t\x1b[?2048$p\x1b[?1000$p\x1b[?1006$p\x1b[>q\x1b[c")
	if tty == nil {
		return
