{"command": "cat > /workspace/oviewer/oviewer.go <<'GOEOF'
package oviewer

import (
	"fmt"
	"os"
	"strconv"
	"strings"

	tcell "github.com/gdamore/tcell/v2"
)

// Oviewer is the main structure.
type Oviewer struct {
	// screen
	screen tcell.Screen
	// documents
	docs      []*Document
	docNum    int
	scr       int // the current document index of the display
	top       int
	column    int
	lastTop   int
	// sizes
	width  int
	height int
	// header
	header int
	// search
	searchWord   string
	searchRegexp *Regexp
	// input
	input      *Input
	inputMode  bool
	// marks
	markNum int
	// the message on the prompt
	message string
	// the style of the body
	styles map[string]tcell.Style
	// quit
	quit bool
	// exit write
	writeOriginal bool
}

// mainLoop runs the main loop.
func (o *Oviewer) mainLoop() error {
	s, err := newScreen(!o.DisableMouse)
	if err != nil {
		return err
	}
	o.screen = s
	defer s.Fini()

	if !o.DisableMouse {
		s.EnableMouse()
	}

	o.setup()

	// draw
	o.draw()

	for !o.quit {
		ev := s.PollEvent()
		switch e := ev.(type) {
		case *tcell.EventKey:
			o.keyAction(e)
		case *tcell.EventResize:
			o.resize()
			o.sync()
		case *tcell.EventMouse:
			o.mouseAction(e)
		case *tcell.EventInterrupt:
			o.sync()
		case *tcell.EventError:
			return e
		case nil:
			//
		}
	}
	return nil
}

// setup initializes the documents and the screen.
func (o *Oviewer) setup() {
	o.width, o.height = o.screen.Size()
	o.styles = o.buildStyles()

	// read the documents
	docs := o.Args
	if len(docs) == 0 {
		// from stdin
		d := NewDocument()
		d.Name = "(STDIN)"
		d.reading = true
		o.docs = append(o.docs, d)
		go func() {
			defer func() { d.reading = false }()
			readDocumentStream(d, os.Stdin)
		}()
	} else {
		for _, name := range docs {
			d := NewDocument()
			d.Name = name
			d.FileName = name
			d.reading = true
			o.docs = append(o.docs, d)
			f := name
			go func() {
				defer func() { d.reading = false }()
				if e := readDocument(d, f); e != nil {
					fmt.Fprintf(os.Stderr, "Error: %s\n", e)
				}
			}()
		}
	}
	o.header = o.Header
	o.top = 0
}

// resize handles the terminal resize.
func (o *Oviewer) resize() {
	w, h := o.screen.Size()
	if w == o.width && h == o.height {
		return
	}
	o.width, o.height = o.height, h
	o.width, o.height = w, h
	o.docs[0].clearWrapCache()
	o.sync()
}

// sync draws the whole screen.
func (o *Oviewer) sync() {
	o.screen.Clear()
	o.drawBody()
	o.drawPrompt()
	o.screen.Show()
}

// draw draws the screen.
func (o *Oviewer) draw() {
	o.drawBody()
	o.drawPrompt()
	o.screen.Show()
}

// drawBody draws the body.
func (o *Oviewer) drawBody() {
	d := o.docs[o.docNum]
	w, h := o.width, o.height
	bodyTop := 0
	if o.header > 0 {
		// header rows
		hn := o.headerRows(d)
		o.drawHeader(d, 0, hn)
		bodyTop = hn
	}
	rows := h - bodyTop - 1
	if o.StatusLine {
		rows = h - bodyTop - 1
	} else {
		rows = h - bodyTop
	}
	o.drawLines(d, bodyTop, rows)
}

// headerRows returns the number of the rows of the header.
func (o *Oviewer) headerRows(d *Document) int {
	n := 0
	if o.Wrap {
		for i := 0; i < o.header; i++ {
			if i >= d.Len() {
				break
			}
			n += d.wrapHeight(i, o.width, o.TabWidth)
		}
	} else {
		n = o.header
	}
	return n
}

// drawHeader draws the header.
func (o *Oviewer) drawHeader(d *Document, y, hn int) {
	for i := 0; i < o.header && y < hn; i++ {
		line := d.GetLine(i)
		o.drawWrapped(d, line, y, i, true)
	}
}

// drawLines draws the body lines.
func (o *Oviewer) drawLines(d *Document, y, rows int) {
	for r := 0; r < rows; r++ {
		lineNum, wrapRow := o.rowToLine(d, o.top+r)
		if lineNum < 0 {
			o.setLine(y+r, "~", tcell.StyleDefault.Foreground(tcell.ColorGray))
			continue
		}
		line := d.GetLine(lineNum)
		o.drawWrapped(d, line, y+r, lineNum, false)
	}
}

// rowToLine returns the line number and the wrap row of the display row.
func (o *Oviewer) rowToLine(d *Document, row int) (int, int) {
	if row < 0 {
		return -1, 0
	}
	n := 0
	for i := 0; i < d.Len(); i++ {
		h := 1
		if o.Wrap {
			h = d.wrapHeight(i, o.width, o.TabWidth)
		}
		if row < n+h {
			return i, row - n
		}
		n += h
	}
	return -1, 0
}

// drawWrapped draws a line (possibly wrapped).
func (o *Oviewer) drawWrapped(d *Document, line string, y, lineNum int, header bool) {
	if !o.Wrap {
		o.setLine(y, line, tcell.StyleDefault)
		return
	}
	cells := convertCells(line, o.TabWidth)
	w := 0
	x := 0
	start := 0
	for i, c := range cells {
		if w+c.w > o.width && i > start {
			o.setCells(y, cells[start:i])
			y++
			w = 0
			start = i
		}
		w += c.w
	}
	o.setCells(y, cells[start:])
}

// setLine draws a single line at the row.
func (o *Oviewer) setLine(y int, s string, st tcell.Style) {
	if y >= o.height-1 && o.StatusLine {
		return
	}
	x := 0
	for _, c := range s {
		if x >= o.width {
			break
		}
		o.screen.SetContent(x, y, c, nil, st)
		x++
	}
	for ; x < o.width; x++ {
		o.screen.SetContent(x, y, ' ', nil, st)
	}
}

// setCells draws the cells at the row.
func (o *Oviewer) setCells(y int, cells []Cell) {
	x := 0
	for _, c := range cells {
		if c.w == 0 {
			continue
		}
		if x >= o.width {
			break
		}
		st := c.s
		if st == tcell.StyleDefault {
			st = tcell.StyleDefault
		}
		o.screen.SetContent(x, y, c.r, nil, st)
		x += c.w
	}
	for ; x < o.width; x++ {
		o.screen.SetContent(x, y, ' ', nil, tcell.StyleDefault)
	}
}

// drawPrompt draws the status line.
func (o *Oviewer) drawPrompt() {
	if !o.StatusLine {
		return
	}
	d := o.docs[o.docNum]
	y := o.height - 1
	name := o.promptName(d)
	o.setPrompt(y, name, o.promptCount(d))
	o.screen.ShowCursor(len(name), y)
}

// promptName returns the name part of the prompt.
func (o *Oviewer) promptName(d *Document) string {
	if o.message != "" {
		return o.message
	}
	name := d.Name
	if name == "" {
		name = "(STDIN)"
	}
	return name + ":"
}

// promptCount returns the count part of the prompt.
func (o *Oviewer) promptCount(d *Document) string {
	total := d.Len()
	lineNum := o.lineAtRow(d, o.top) + 1
	if d.Reading() {
		return fmt.Sprintf("(%d/%d...)", lineNum, total)
	}
	return fmt.Sprintf("(%d/%d)", lineNum, total)
}

// lineAtRow returns the line number at the display row.
func (o *Oviewer) lineAtRow(d *Document, row int) int {
	n, _ := o.rowToLine(d, row)
	return n
}

// setPrompt draws the prompt line.
func (o *Oviewer) setPrompt(y int, name, count string) {
	st := tcell.StyleDefault
	if o.config.Prompt.Normal.InvertColor {
		st = st.Reverse(true)
	}
	x := 0
	for _, c := range name {
		if x >= o.width {
			break
		}
		o.screen.SetContent(x, y, c, nil, st)
		x++
	}
	if count == "" {
		count = ""
	}
	cnt := count
	cl := len([]rune(cnt))
	cx := o.width - cl
	if cx < x {
		cx = x
	}
	for ; x < cx; x++ {
		o.screen.SetContent(x, y, ' ', nil, tcell.StyleDefault)
	}
	for _, c := range cnt {
		if x >= o.width {
			break
		}
		o.screen.SetContent(x, y, c, nil, tcell.StyleDefault)
		x++
	}
	for ; x < o.width; x++ {
		o.screen.SetContent(x, y, ' ', nil, tcell.StyleDefault)
	}
}

// keyAction handles the key event.
func (o *Oviewer) keyAction(ev *tcell.EventKey) {
	action := o.findAction(ev)
	if action == "" {
		return
	}
	switch action {
	case "exit":
		o.quit = true
	case "write_exit":
		o.writeOriginal = true
		o.quit = true
	case "down":
		o.moveDown(1)
	case "up":
		o.moveUp(1)
	case "top":
		o.top = 0
	case "bottom":
		o.bottom()
	case "page_down":
		o.pageDown()
	case "page_up":
		o.pageUp()
	case "page_half_down":
		o.pageHalfDown()
	case "page_half_up":
		o.pageHalfUp()
	case "left":
		o.scrollLeft(1)
	case "right":
		o.scrollRight(1)
	case "half_left":
		o.scrollLeft(o.width / 2)
	case "half_right":
		o.scrollRight(o.width / 2)
	default:
		return
	}
	o.draw()
}

// findAction returns the action name of the key event.
func (o *Oviewer) findAction(ev *tcell.EventKey) string {
	for action, keys := range o.Keybind {
		for _, key := range keys {
			if matchKey(ev, key) {
				return action
			}
		}
	}
	return ""
}

// moveDown moves the top down.
func (o *Oviewer) moveDown(n int) {
	o.top += n
	o.adjustTop()
}

// moveUp moves the top up.
func (o *Oviewer) moveUp(n int) {
	o.top -= n
	o.adjustTop()
}

// adjustTop adjusts the top position.
func (o *Oviewer) adjustTop() {
	if o.top < 0 {
		o.top = 0
	}
	d := o.docs[o.docNum]
	max := o.maxTop(d)
	if o.top > max {
		o.top = max
	}
}

// maxTop returns the maximum top row.
func (o *Oviewer) maxTop(d *Document) int {
	rows := o.bodyRows()
	return o.bottomTop(d, rows)
}

// bodyRows returns the number of the body rows.
func (o *Oviewer) bodyRows() int {
	rows := o.height - 1
	if o.header > 0 {
		rows -= o.headerRows(o.docs[o.docNum])
	}
	if rows < 0 {
		rows = 0
	}
	return rows
}

// bottomTop returns the top row at the bottom.
func (o *Oviewer) bottomTop(d *Document, height int) int {
	total := o.totalRows(d)
	if total <= height {
		return 0
	}
	return total - height + 1
}

// totalRows returns the total number of the display rows.
func (o *Oviewer) totalRows(d *Document) int {
	total := 0
	for i := 0; i < d.Len(); i++ {
		total += d.wrapHeight(i, o.width, o.TabWidth)
	}
	return total
}

// pageDown moves a page down.
func (o *Oviewer) pageDown() {
	o.moveDown(o.bodyRows())
}

// pageUp moves a page up.
func (o *Oviewer) pageUp() {
	o.moveUp(o.bodyRows())
}

// pageHalfDown moves a half page down.
func (o *Oviewer) pageHalfDown() {
	o.moveDown(o.bodyRows() / 2)
}

// pageHalfUp moves a half page up.
func (o *Oviewer) pageHalfUp() {
	o.moveUp(o.bodyRows() / 2)
}

// scrollLeft scrolls left.
func (o *Oviewer) scrollLeft(n int) {
	o.column -= n
	if o.column < 0 {
		o.column = 0
	}
}

// scrollRight scrolls right.
func (o *Oviewer) scrollRight(n int) {
	o.column += n
}

// bottom moves to the bottom.
func (o *Oviewer) bottom() {
	o.top = o.bottomTop(o.docs[o.docNum], o.bodyRows())
}

// mouseAction handles the mouse event.
func (o *Oviewer) mouseAction(ev *tcell.EventMouse) {
}

// writeOriginal writes the original content.
func (o *Oviewer) writeOriginalLines() {
	d := o.docs[o.docNum]
	for _, line := range d.getLines(0, d.Len()) {
		fmt.Println(line)
	}
}

// parseJumpTarget parses the jump target.
func parseJumpTarget(s string, height int) int {
	if s == "" {
		return 0
	}
	if strings.HasPrefix(s, ".") {
		n, err := strconv.Atoi(s[1:])
		if err == nil {
			return height / n
		}
		return 0
	}
	if strings.HasSuffix(s, "%") {
		p, err := strconv.Atoi(s[:len(s)-1])
		if err == nil {
			return height * p / 100
		}
		return 0
	}
	n, err := strconv.Atoi(s)
	if err == nil {
		return n
	}
	return 0
}
GOEOF
echo ok"}

