			d.reading = true
			o.docs = append(o.docs, d)
			f := name
			go func() {
				defer func() { d.reading = false }()
				if e := readDocument(d, f); e != nil {
					fmt.Fprintf(os.Stderr, "Error: %s\n", e)
				}
			}()
		}
	}
	o.header = o.Header
	o.top = 0
}

// resize handles the terminal resize.
func (o *Oviewer) resize() {
	w, h := o.screen.Size()
	if w == o.width && h == o.height {
		return
	}
	o.width, o.height = o.height, h
	o.width, o.height = w, h
	o.docs[0].clearWrapCache()
	o.sync()
}

// sync draws the whole screen.
func (o *Oviewer) sync() {
	o.screen.Clear()
	o.drawBody()
	o.drawPrompt()
	o.screen.Show()
}

// draw draws the screen.
func (o *Oviewer) draw() {
	o.drawBody()
	o.drawPrompt()
	o.screen.Show()
}

// drawBody draws the body.
func (o *Oviewer) drawBody() {
	d := o.docs[o.docNum]
	w, h := o.width, o.height
	bodyTop := 0
	if o.header > 0 {
		// header rows
		hn := o.headerRows(d)
		o.drawHeader(d, 0, hn)
		bodyTop = hn
	}
	rows := h - bodyTop - 1
	if o.StatusLine {
		rows = h - bodyTop - 1
	} else {
		rows = h - bodyTop
	}
	o.drawLines(d, bodyTop, rows)
}

// headerRows returns the number of the rows of the header.
func (o *Oviewer) headerRows(d *Document) int {
	n := 0
	if o.Wrap {
		for i := 0; i < o.header; i++ {
			if i >= d.Len() {
				break
			}
			n += d.wrapHeight(i, o.width, o.TabWidth)
		}
	} else {
		n = o.header
	}
	return n
}

// drawHeader draws the header.
func (o *Oviewer) drawHeader(d *Document, y, hn int) {
	for i := 0; i < o.header && y < hn; i++ {
		line := d.GetLine(i)
		o.drawWrapped(d, line, y, i, true)
	}
}

// drawLines draws the body lines.
func (o *Oviewer) drawLines(d *Document, y, rows int) {
	for r := 0; r < rows; r++ {
		lineNum, wrapRow := o.rowToLine(d, o.top+r)
		if lineNum < 0 {
			o.setLine(y+r, "~", tcell.StyleDefault.Foreground(tcell.ColorGray))
			continue
		}
		line := d.GetLine(lineNum)
		o.drawWrapped(d, line, y+r, lineNum, false)
	}
}

// rowToLine returns the line number and the wrap row of the display row.
func (o *Oviewer) rowToLine(d *Document, row int) (int, int) {
	if row < 0 {
		return -1, 0
	}
	n := 0
	for i := 0; i < d.Len(); i++ {
		h := 1
		if o.Wrap {
			h = d.wrapHeight(i, o.width, o.TabWidth)
		}
		if row < n+h {
			return i, row - n
		}
		n += h
	}
	return -1, 0
}

// drawWrapped draws a line (possibly wrapped).
func (o *Oviewer) drawWrapped(d *Document, line string, y, lineNum int, header bool) {
	if !o.Wrap {
		o.setLine(y, line, tcell.StyleDefault)
		return
	}
	cells := convertCells(line, o.TabWidth)
	w := 0
	x := 0
	start := 0
	for i, c := range cells {
		if w+c.w > o.width && i > start {
			o.setCells(y, cells[start:i])
			y++
			w = 0
			start = i
		}
		w += c.w
	}
	o.setCells(y, cells[start:])
}

// setLine draws a single line at the row.
func (o *Oviewer) setLine(y int, s string, st tcell.Style) {
	if y >= o.height-1 && o.StatusLine {
		return
	}
	x := 0
	for _, c := range s {
		if x >= o.width {
			break
		}
		o.screen.SetContent(x, y, c, nil, st)
		x++
	}
	for ; x < o.width; x++ {
		o.screen.SetContent(x, y, ' ', nil, st)
	}
}

// setCells draws the cells at the row.
func (o *Oviewer) setCells(y int, cells []Cell) {
	x := 0
	for _, c := range cells {
		if c.w == 0 {
			continue
		}
		if x >= o.width {
			break
		}
		st := c.s
		if st == tcell.StyleDefault {
			st = tcell.StyleDefault
		}
		o.screen.SetContent(x, y, c.r, nil, st)
		x += c.w
	}
	for ; x < o.width; x++ {
		o.screen.SetContent(x, y, ' ', nil, tcell.StyleDefault)
	}
}

// drawPrompt draws the status line.
func (o *Oviewer) drawPrompt() {
	if !o.StatusLine {
		return
	}
	d := o.docs[o.docNum]
	y := o.height - 1
	name := o.promptName(d)
	o.setPrompt(y, name, o.promptCount(d))
	o.screen.ShowCursor(len(name), y)
}

// promptName returns the name part of the prompt.
func (o *Oviewer) promptName(d *Document) string {
	if o.message != "" {
		return o.message
	}
	name := d.Name
	if name == "" {
		name = "(STDIN)"
	}
	return name + ":"
