// promptCount returns the count part of the prompt.
func (o *Oviewer) promptCount(d *Document) string {
	total := d.Len()
	lineNum := o.lineAtRow(d, o.top) + 1
	if d.Reading() {
		return fmt.Sprintf("(%d/%d...)", lineNum, total)
	}
	return fmt.Sprintf("(%d/%d)", lineNum, total)
}

// lineAtRow returns the line number at the display row.
func (o *Oviewer) lineAtRow(d *Document, row int) int {
	n, _ := o.rowToLine(d, row)
