package oviewer

import (
	"math"

	tcell "github.com/gdamore/tcell/v2"
	colorful "github.com/lucasb-eyer/go-colorful"
)

// buildStyles builds the styles from the config.
func (o *Oviewer) buildStyles() map[string]tcell.Style {
	m := map[string]tcell.Style{}
	st := o.General.Style
	m["Alternate"] = o.styleOf(st.Alternate, tcell.StyleDefault)
	m["Header"] = o.styleOf(st.Header, tcell.StyleDefault)
	m["Body"] = o.styleOf(st.Body, tcell.StyleDefault)
	m["LineNumber"] = o.styleOf(st.LineNumber, tcell.StyleDefault)
	m["SearchHighlight"] = o.styleOf(st.SearchHighlight, tcell.StyleDefault)
	m["ColumnHighlight"] = o.styleOf(st.ColumnHighlight, tcell.StyleDefault)
	m["MarkLine"] = o.styleOf(st.MarkLine, tcell.StyleDefault)
	m["SectionLine"] = o.styleOf(st.SectionLine, tcell.StyleDefault)
	m["VerticalHeader"] = o.styleOf(st.VerticalHeader, tcell.StyleDefault)
	m["JumpTargetLine"] = o.styleOf(st.JumpTargetLine, tcell.StyleDefault)
	m["Ruler"] = o.styleOf(st.Ruler, tcell.StyleDefault)
	m["HeaderBorder"] = o.styleOf(st.HeaderBorder, tcell.StyleDefault)
	m["SectionHeaderBorder"] = o.styleOf(st.SectionHeaderBorder, tcell.StyleDefault)
	m["VerticalHeaderBorder"] = o.styleOf(st.VerticalHeaderBorder, tcell.StyleDefault)
	m["StyleOverStrike"] = o.styleOf(o.config.StyleOverStrike, tcell.StyleDefault)
	m["StyleOverLine"] = o.styleOf(o.config.StyleOverLine, tcell.StyleDefault)
	return m
}

// styleOf converts the style config to a tcell style.
func (o *Oviewer) styleOf(c StyleConfig, base tcell.Style) tcell.Style {
	st := base
	if c.Foreground != "" {
		st = st.Foreground(lookupColor(c.Foreground))
	}
	if c.Background != "" {
		st = st.Background(lookupColor(c.Background))
	}
	if c.UnderlineColor != "" {
		st = st.Underline(lookupColor(c.UnderlineColor))
	}
	if c.Bold {
		st = st.Bold(true)
	}
	if c.Blink {
		st = st.Blink(true)
	}
	if c.Dim {
		st = st.Dim(true)
	}
	if c.Italic {
		st = st.Italic(true)
	}
	if c.Reverse {
		st = st.Reverse(true)
	}
	if c.StrikeThrough {
		st = st.StrikeThrough(true)
	}
	if c.Underline {
		st = st.Underline(true)
	}
	return st
}

// lookupColor returns the color of the name.
func lookupColor(name string) tcell.Color {
	if c, ok := tcell.ColorNames[name]; ok {
		return c
	}
	if len(name) > 1 && name[0] == '#' {
		if c, err := colorOfHex(name); err == nil {
			return c
		}
	}
	return tcell.ColorDefault
}

func colorOfHex(s string) (tcell.Color, error) {
	if len(s) != 7 {
		return tcell.ColorDefault, errColor
	}
	var r, g, b int
	_, err := fmtSscanf(s[1:], "%02x%02x%02x", &r, &g, &b)
	if err != nil {
		return tcell.ColorDefault, err
	}
	return tcell.NewRGBColor(int32(r), int32(g), int32(b)), nil
}

var errColor = &colorError{"invalid color"}

type colorError struct{ msg string }

func (e *colorError) Error() string { return e.msg }

// findColor returns the nearest palette color.
func findColor(c tcell.Color, palette []tcell.Color) tcell.Color {
	r, g, b := c.RGB()
	c1 := colorful.Color{R: float64(r) / 255.0, G: float64(g) / 255.0, B: float64(b) / 255.0}
	match := tcell.ColorDefault
	dist := math.MaxFloat64
	for _, d := range palette {
		r2, g2, b2 := d.RGB()
		c2 := colorful.Color{R: float64(r2) / 255.0, G: float64(g2) / 255.0, B: float64(b2) / 255.0}
		nd := c1.DistanceCIE76(c2)
		if math.IsNaN(nd) {
			nd = math.MaxFloat64
		}
		if nd < dist {
			match = d
			dist = nd
		}
	}
	return match
}

// fmtSscanf is a wrapper of fmt.Sscanf.
func fmtSscanf(s string, format string, args ...interface{}) (int, error) {
	return scanf(s, format, args...)
}
GOEOF
