{"command": "cd /workspace && python3 - <<'PY'
import subprocess,os,time,pty,select,fcntl,struct,termios,signal
def run(cmd, cols=60, rows=8, dur=3.0, replies=1):
    pid,fd=pty.fork()
    if pid==0:
        e=dict(os.environ); e['TERM']='xterm-256color'; e['COLUMNS']=str(cols); e['LINES']=str(rows)
        os.environ.clear(); os.environ.update(e)
        os.execvp('/bin/sh',['/bin/sh','-c',cmd])
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH',rows,cols,0,0))
    out=b''; t=time.time(); n=0
    resp={b'\x1b[18t': b'\x1b[8;8;60t', b'\x1b[?2048$p': b'\x1b[?2048;2$y', b'\x1b[?1000$p': b'\x1b[?1000;2$y', b'\x1b[?1006$p': b'\x1b[?1006;2$y', b'\x1b[>q': b'\x1b[>1;2q', b'\x1b[c': b'\x1b[?62;22;6c'}
    ev=[]
    while time.time()-t<dur:
        r,_,_=select.select([fd],[],[],0.02)
        if r:
            try: d=os.read(fd,65536)
            except OSError: break
            if not d: break
            out+=d; ev.append((round((time.time()-t)*1000), len(d)))
            for q,t2 in resp.items():
                if q in d and n < replies:
                    n+=1
                    os.write(fd, t2)
    os.kill(pid,9); os.waitpid(pid,0); os.close(fd)
    return out,ev
for rep in (0,1,2,3,6):
    o,ev=run('./executable testdata/test.txt', replies=rep)
    print('replies=%d'%rep, ev[:8])
PY"}

