func queryTerminal(timeout time.Duration) {
	f, err := os.OpenFile("/dev/tty", os.O_RDONLY, 0)
	if err != nil {
		os.Stdout.WriteString("\\x1b[18t\\x1b[?2048$p\\x1b[?1000$p\\x1b[?1006$p\\x1b[>q\\x1b[c")
		return
	}
	defer f.Close()
	f.WriteString("\\x1b[18t\\x1b[?2048$p\\x1b[?1000$p\\x1b[?1006$p\\x1b[>q\\x1b[c")
	ch := make(chan bool, 1)
	go func() {
		buf := make([]byte, 1024)
		count := 0
		for count < 6 {
			n, err := f.Read(buf)
			if err != nil || n <= 0 {
				break
			}
			count += countResponses(buf[:n])
		}
		ch <- true
	}()
	select {
	case <-ch:
	case <-time.After(timeout):
	}
}

// countResponses counts the terminal responses in the buffer.
func countResponses(buf []byte) int {
	count := 0
	for i := 0; i < len(buf); i++ {
		if buf[i] != 0x1b {
			continue
		}
		if i+1 >= len(buf) {
			break
		}
		if buf[i+1] == '[' {
