package main

import (
	"bytes"
	"compress/bzip2"
	"compress/gzip"
	"fmt"
	"io"
	"os"
)

func readLines(r io.Reader) []string {
	const chunkSize = 4096
	lines := make([]string, 0, chunkSize)
	buffer := make([]byte, 0, 64*1024)
	tmp := make([]byte, 64*1024)
	for {
		n, err := r.Read(tmp)
		if n > 0 {
			buffer = append(buffer, tmp[:n]...)
			idx := bytes.IndexByte(buffer, '\n')
			for idx >= 0 {
				line := buffer[:idx]
				line = bytes.TrimSuffix(line, []byte("\r"))
				lines = append(lines, string(line))
				buffer = buffer[idx+1:]
				idx = bytes.IndexByte(buffer, '\n')
			}
		}
		if err != nil {
			break
		}
	}
	if len(buffer) > 0 {
		line := bytes.TrimSuffix(buffer, []byte("\r"))
		lines = append(lines, string(line))
	}
	return lines
}

func main() {
	f, _ := os.Open(os.Args[1])
	buf := make([]byte, 64*1024)
	head, err := io.ReadFull(f, buf)
	if err != nil && err != io.ErrUnexpectedEOF {
		if err == io.EOF { fmt.Println("empty"); return }
		fmt.Println("err", err); return
	}
	_ = head
	br := io.MultiReader(bytes.NewReader(buf[:head]), f)
	lines := readLines(br)
	fmt.Println("lines:", len(lines))
	for i, l := range lines {
		fmt.Printf("%d: %q\n", i, l)
	}
}
