import re
def render(o, cols=60, rows=8):
    # simple ANSI screen emulator
    grid=[[' ']*cols for _ in range(rows)]
    x=y=0
    i=0
    while i<len(o):
        if o[i:i+1]==b'\x1b':
            j=i+1
            if j<len(o) and o[j:j+1]==b'[':
                j+=1
                while j<len(o) and o[j:j+1] not in b'HJKmABCfhrl':
                    j+=1
                seq=o[i:j+1]
                m=re.match(rb'\x1b\[(\d+);(\d+)H', seq)
                if m: y=int(m.group(1))-1; x=int(m.group(2))-1
                m=re.match(rb'\x1b\[(\d+)H', seq)
                if m: y=int(m.group(1))-1
                i=j+1
                continue
            i=j+1
            continue
        c=o[i:i+1]
        grid[y][x]=c.decode('latin1')
        x+=1
        i+=1
    return [''.join(r).rstrip() for r in grid]
for b in ['./mybin','./executable']:
    o=cap('%s testdata/normal.txt'%b, dur=1.5)
    parts=o.split(b'\x1b[?2026l')
