    x=y=0
    curstyle=''
    i=0
    n=len(o)
    while i<n:
        c=o[i:i+1]
        if c==b'\x1b':
            j=i+1
            if j<n and o[j:j+1]==b'[':
                j+=1
                while j<n and o[j:j+1] not in b'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijkmlnopqrstuvwxyz':
                    j+=1
                if j>=n: break
                seq=o[i:j+1]; final=o[j:j+1]
                if final==b'H':
                    m=re.match(rb'\x1b\[(\d*);?(\d*)H', seq)
                    if m:
                        y=(int(m.group(1))-1) if m.group(1) else 0
                        x=(int(m.group(2))-1) if m.group(2) else 0
                elif final==b'J':
                    # erase from cursor to end of display
                    m=re.match(rb'\x1b\[(\d*)J', seq)
                    mode=int(m.group(1)) if m.group(1) else 0
                    if mode==0:
                        for xx in range(x, cols): grid[y][xx]=' '; style[y][xx]=''
                        for yy in range(y+1, rows):
                            for xx in range(cols): grid[yy][xx]=' '; style[yy][xx]=''
                    elif mode==2:
                        for yy in range(rows):
                            for xx in range(cols): grid[yy][xx]=' '; style[yy][xx]=''
                elif final==b'K':
                    for xx in range(x, cols): grid[y][xx]=' '; style[y][xx]=''
                elif final==b'm':
                    curstyle=seq.decode('latin1')
                x=x; i=j+1
                continue
            else:
                i=i+2
                continue
        # printable
        b=o[i]
        if b>=0x20:
            if y<rows and x<cols:
                grid[y][x]=chr(b)
                style[y][x]=curstyle
            x+=1
        i+=1
    return [''.join(r).rstrip() for r in grid]
