import subprocess,os,time,pty,select,fcntl,struct,termios,signal
def run(keys, dur=3.0, kd=1.5):
    pid,fd=pty.fork()
    if pid==0:
        e=dict(os.environ); e['TERM']='xterm-256color'; e['COLUMNS']='60'; e['LINES']='8'
        os.environ.clear(); os.environ.update(e)
        os.execvp('/bin/sh',['/bin/sh','-c','./mybin testdata/ps.txt'])
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH',8,60,0,0))
    out=b''; t=time.time(); ev=[]
    resp={b'\x1b[18t': b'\x1b[8;8;60t', b'\x1b[?2048$p': b'\x1b[?2048;2$y', b'\x1b[?1000$p': b'\x1b[?1000;2$y', b'\x1b[?1006$p': b'\x1b[?1006;2$y', b'\x1b[>q': b'\x1b[>1;2q', b'\x1b[c': b'\x1b[?62;22;6c'}
    kt=t+kd; ki=0
    while time.time()-t<dur:
        r,_,_=select.select([fd],[],[],0.02)
        if r:
            try: d=os.read(fd,65536)
            except OSError: break
            if not d: break
            out+=d; ev.append((round((time.time()-t)*1000), d))
            for q,t2 in resp.items():
                if q in d: os.write(fd, t2)
        else:
            if ki<len(keys) and time.time()>kt:
                os.write(fd, keys[ki]); ev.append((round((time.time()-t)*1000), b'KEY'+keys[ki])); ki+=1; kt=time.time()+kd
    os.kill(pid,9); os.waitpid(pid,0); os.close(fd)
    return ev
for keys,name in [([b'\x1b[B'],'Down'),([b'q'],'q'),([b'\x04'],'C-d'),([b'\x1b[A'],'Up')]:
    ev=run(keys)
    print('===',name)
    for tm,d in ev:
        if d.startswith(b'KEY'): print('  ',tm,d)
        else: print('  ',tm,len(d),repr(d[:60]))
