	"github.com/noborus/ov/oviewer"
)

func main() {
	line := "USER         PID %CPU %MEM    VSZ   RSS TTY      STAT START   TIME COMMAND"
	cells := oviewer.ConvertCellsPub(line, 8)
	rows := oviewer.SplitRowsPub(cells, 60)
	fmt.Println("num rows:", len(rows))
	for i, r := range rows {
		s := ""
		for _, c := range r { s += string(c.R) }
		fmt.Printf("%d: %q\n", i, s)
	}
	fmt.Println("height:", oviewer.WrapLineHeightPub(line, 60, 8))
}
