package oviewer

import (
	"strings"

	tcell "github.com/gdamore/tcell/v2"
)

// Input is the state of the input prompt.
type Input struct {
	// mode is the mode of the input prompt.
	mode string
	// prompt is the prefix of the input prompt.
	prompt string
	// cursorStr is the input string.
	cursorStr string
	// cursorX is the cursor position.
	cursorX int
	// the search options
	caseSensitive bool
	smartCase     bool
	regexpSearch  bool
	incsearch     bool
	nonMatch      bool
	// the history
	history  []string
	historyP int
	// the candidates for the view mode
	candidates []string
	candidateP int
	// the previous top position
	prevTop int
}

// promptPrefix returns the prefix of the input prompt.
func (i *Input) promptPrefix() string {
	switch i.mode {
	case "search", "backsearch":
		var sb strings.Builder
		if i.regexpSearch {
			sb.WriteString("(R)")
		}
		if i.incsearch {
			sb.WriteString("(I)")
		}
		if i.caseSensitive {
			sb.WriteString("(Aa)")
		}
		if i.smartCase {
			sb.WriteString("(S)")
		}
		if i.mode == "search" {
			sb.WriteString("/")
		} else {
			sb.WriteString("?")
		}
		return sb.String()
	case "goto":
		return "Goto line:"
	case "delimiter":
		return "Delimiter:"
	case "header":
		return "Header length:"
	case "skip_lines":
		return "Skip lines:"
	case "tabwidth":
		return "TAB width:"
	case "multi_color":
		return "Multi color:"
	case "jump_target":
		return "Jump target line:"
	case "convert_type":
		return "Convert:"
	case "vertical_header":
		return "Vertical header length:"
	case "header_column":
		return "Header column:"
	case "section_delimiter":
		return "Section delimiter:"
	case "section_start":
		return "Section start:"
	case "mark_number":
		return "Mark number:"
	case "mark_pattern":
		return "*"
	case "filter":
		return "&"
	case "set_view_mode":
		return "Mode:"
	case "watch_interval":
		return "Watch interval:"
	}
	return ""
}

// newInput returns a new Input.
func newInput(mode string) *Input {
	i := &Input{mode: mode, incsearch: true}
	return i
}

// setModeOptions sets the options from the settings.
func (i *Input) setModeOptions(caseSensitive, smartCase, regexpSearch, incsearch bool) {
	i.caseSensitive = caseSensitive
	i.smartCase = smartCase
	i.regexpSearch = regexpSearch
	i.incsearch = incsearch
}

// keyHandler handles the key event in the input mode.
func (o *Oviewer) keyHandler(ev *tcell.EventKey) {
	i := o.input
	if i == nil {
		return
	}
	action := o.findAction(ev, o.inputKeybind)
	switch action {
	case "input_casesensitive":
		i.caseSensitive = !i.caseSensitive
	case "input_smart_casesensitive":
		i.smartCase = !i.smartCase
	case "input_regexp_search":
		i.regexpSearch = !i.regexpSearch
	case "input_incsearch":
		i.incsearch = !i.incsearch
		if i.incsearch && i.mode == "search" || i.mode == "backsearch" {
			o.inputSearch()
		}
	case "input_non_match":
		i.nonMatch = !i.nonMatch
	case "input_previous":
		o.inputHistory(false)
	case "input_next":
		o.inputHistory(true)
	case "input_copy":
		//
	case "input_paste":
		//
	default:
		// input the character
		o.inputChar(ev)
	}
	o.drawPromptOnly()
}

// inputChar handles the character input.
func (o *Oviewer) inputChar(ev *tcell.EventKey) {
	i := o.input
	if i == nil {
		return
	}
	switch ev.Key() {
	case tcell.KeyEnter, tcell.KeyCtrlJ, tcell.KeyCtrlM:
		o.inputEnter()
		return
	case tcell.KeyEsc, tcell.KeyCtrlC:
		o.cancelInput()
		return
	case tcell.KeyBackspace, tcell.KeyBackspace2, tcell.KeyCtrlH:
		if len(i.cursorStr) > 0 {
			// remove the last rune
			s := i.cursorStr
			r := []rune(s)
			i.cursorStr = string(r[:len(r)-1])
			if i.cursorX > len([]rune(i.cursorStr)) {
				i.cursorX = len([]rune(i.cursorStr))
			}
			o.inputSearch()
		}
		return
	case tcell.KeyDelete:
		//
		return
	case tcell.KeyTab:
		//
		return
	}
	if ev.Key() == tcell.KeyRune {
		c := ev.Rune()
		if c == '!' && i.mode == "search" || i.mode == "backsearch" {
			i.nonMatch = !i.nonMatch
		}
		i.cursorStr += string(c)
		i.cursorX = len([]rune(i.cursorStr))
		o.inputSearch()
	}
}

// inputEnter commits the input.
func (o *Oviewer) inputEnter() {
	i := o.input
	if i == nil {
		return
	}
	o.inputMode = false
	switch i.mode {
	case "search", "backsearch":
		o.searchWord = i.cursorStr
		o.searchNext()
	case "goto":
		o.gotoLine(i.cursorStr)
	case "delimiter":
		o.setColumnDelimiter(i.cursorStr)
	case "header":
		o.setHeader(i.cursorStr)
	case "skip_lines":
		o.setSkipLines(i.cursorStr)
	case "tabwidth":
		o.setTabWidth(i.cursorStr)
	case "multi_color":
		o.setMultiColor(i.cursorStr)
	case "jump_target":
		o.setJumpTarget(i.cursorStr)
	case "vertical_header":
		o.setVerticalHeader(i.cursorStr)
	case "header_column":
		o.setHeaderColumn(i.cursorStr)
	case "section_delimiter":
		o.setSectionDelimiter(i.cursorStr)
	case "section_start":
		o.setSectionStart(i.cursorStr)
	case "mark_number":
		o.gotoMark(i.cursorStr)
	case "set_view_mode":
		o.setViewMode(i.cursorStr)
	case "watch_interval":
		o.setWatchInterval(i.cursorStr)
	case "filter":
		o.setFilter(i.cursorStr)
	}
	o.input = nil
	o.draw()
}

// cancelInput cancels the input.
func (o *Oviewer) cancelInput() {
	i := o.input
	if i == nil {
		return
	}
	o.inputMode = false
	if i.mode == "search" || i.mode == "backsearch" {
		// restore the previous position
		o.top = i.prevTop
		o.searchWord = ""
		o.searchRegexp = nil
	}
	o.input = nil
	o.draw()
}

// inputHistory moves the input history.
func (o *Oviewer) inputHistory(next bool) {
	i := o.input
	if i == nil {
		return
	}
	if len(i.history) == 0 {
		return
	}
	if next {
		i.historyP--
	} else {
		i.historyP++
	}
	if i.historyP < 0 {
		i.historyP = 0
	}
	if i.historyP > len(i.history) {
		i.historyP = len(i.history)
	}
	idx := len(i.history) - 1 - i.historyP
	if idx < 0 {
