// startInput starts the input mode.
func (o *Oviewer) startInput(mode string) {
	i := newInput(mode)
	i.setModeOptions(o.CaseSensitive, o.SmartCaseSensitive, o.RegexpSearch, o.Incsearch)
	i.prevTop = o.top
	o.input = i
	o.inputMode = true
	o.drawPromptOnly()
}

// inputSearch runs the incremental search.
func (o *Oviewer) inputSearch() {
	i := o.input
	if i == nil {
		return
	}
	if i.mode == "search" || i.mode == "backsearch" {
		if i.incsearch && i.cursorStr != "" {
			o.searchWord = i.cursorStr
			o.searchNonMatch = i.nonMatch
			o.searchNext()
		} else {
			o.top = i.prevTop
			o.searchWord = ""
			o.searchRegexp = nil
		}
	}
}

// searchNext searches the next match.
func (o *Oviewer) searchNext() {
	d := o.docs[o.docNum]
	if o.searchWord == "" {
		return
	}
	re := o.searchRegexpFor(o.searchWord)
	o.searchRegexp = re
	n := o.searchLine(d, o.top, re, o.searchWord)
	if n >= 0 {
		o.top = o.rowOfLine(d, n)
	}
	o.adjustTop()
}

// searchRegexpFor returns the regexp for the search word.
func (o *Oviewer) searchRegexpFor(word string) *Regexp {
	if o.RegexpSearch {
		return newRegexp(word)
	}
	return nil
}

// searchLine searches the line that matches the word.
func (o *Oviewer) searchLine(d *Document, start int, re *Regexp, word string) int {
	total := d.Len()
	cs := o.CaseSensitive
	if o.SmartCaseSensitive && hasUpper(word) {
		cs = true
	}
	for i := 0; i < total; i++ {
		n := (start + i) % total
		line := d.GetLine(n)
		if matchLine(line, word, re, cs) {
			return n
		}
	}
	return -1
}

// matchLine returns true if the line matches.
func matchLine(line string, word string, re *Regexp, caseSensitive bool) bool {
	if re != nil {
		return re.MatchString(line)
	}
	if word == "" {
		return false
	}
	if caseSensitive {
		return strings.Contains(line, word)
	}
	return strings.Contains(strings.ToLower(line), strings.ToLower(word))
}

// hasUpper returns true if the string has an uppercase character.
func hasUpper(s string) bool {
	for _, c := range s {
		if c >= 'A' && c <= 'Z' {
			return true
		}
	}
	return false
}

// rowOfLine returns the display row of the line.
func (o *Oviewer) rowOfLine(d *Document, line int) int {
	if !o.Wrap {
		return line
	}
	row := 0
	for i := 0; i < line && i < d.Len(); i++ {
		row += d.wrapHeight(i, o.width, o.TabWidth)
	}
	return row
}
