// gotoLine moves to the specified line.
func (o *Oviewer) gotoLine(s string) {
	d := o.docs[o.docNum]
	total := d.Len()
	if s == "" {
		return
	}
	if strings.HasSuffix(s, "%") {
		p := atoi(s[:len(s)-1])
		o.top = o.rowOfLine(d, total*p/100)
		o.adjustTop()
		return
	}
	if strings.HasPrefix(s, ".") {
		n := atoi(s[1:])
		if n > 0 {
			o.top += n
			o.adjustTop()
		}
		return
	}
	n := atoi(s)
	if n > 0 {
		o.top = o.rowOfLine(d, n-1)
		o.adjustTop()
		return
