import re
def msg(keys, args='testdata/ps.txt', dur=3.0):
    o=cap('./executable %s'%args, dur=dur, cols=70, rows=8, keys=keys)
    parts=o.split(b'\x1b[?2026l')
    ps=[p for p in parts if b'8;1H' in p]
    out=[]
    for p in ps[-3:]:
        m=re.search(rb'\x1b\[8;1H(\x1b\[m)?([^\x1b]{0,45})', p)
        if m: out.append(m.group(2))
    return out
tests=[('goto',[b'g',b'5',b'\r']),('delimiter',[b'd',b'|',b'\r']),('header',[b'H',b'2',b'\r']),('skip',[b'\x13',b'2',b'\r']),('tab',[b't',b'4',b'\r']),('multicolor',[b'.',b'E',b'\r']),('vertical',[b'y',b'5',b'\r']),('headercol',[b'Y',b'3',b'\r']),('jump',[b'j',b'.',b'5',b'\r']),('viewmode',[b'p',b'\r']),('section_del',[b'\x1bd',b'^',b'#',b'\r']),('convert',[b'\x1bt',b'\r']),('cancel',[b'/',b'a',b'\x1b'])]
for name,keys in tests:
    print('%-14s'%name, [x for x in msg(keys)])
PY"}

